import time
from typing import Any, Callable


def retry(fn: Callable[[], Any], max_attempts: int, delay: float = 0.0) -> Any:
    last_exc: BaseException
    for attempt in range(max_attempts):
        try:
            return fn()
        except Exception as exc:
            last_exc = exc
            if attempt < max_attempts - 1 and delay > 0.0:
                time.sleep(delay)
    raise last_exc

from typing import Dict


def parse_env_file(path: str) -> Dict[str, str]:
    result: Dict[str, str] = {}
    with open(path) as f:
        for raw_line in f:
            line = raw_line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" not in line:
                continue
            key, _, value = line.partition("=")
            key = key.strip()
            value = value.strip().strip("'\"")
            if key:
                result[key] = value
    return result
